// make.fun's public API, read-only and same for every caller.
//
// Answers stay in memory for a minute, then revalidate with If-None-Match: a

const ORIGIN = 'https://make.fun';
const TTL_MS = 60_000;
const MAX_ENTRIES = 20;
const listeners = new Set();
const memory = new Map();
let boardItems = null;

const stats = { requests: 0, network: 0, revalidated: 0, notModified: 0, memoryHits: 0, stale: 0, errors: 0, lastUpdated: null };

class ApiError extends Error {
  constructor(message, { status = 0, code = '', retryAfter = 0 } = {}) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
    this.retryAfter = retryAfter;
  }
}

export function subscribeCache(listener) {
  listeners.add(listener);
  listener({ lastUpdated: stats.lastUpdated });
  return () => listeners.delete(listener);
}

function emit() {
  for (const listener of listeners) {
    try { listener({ lastUpdated: stats.lastUpdated }); } catch { /* never break a view */ }
  }
}

function trimMemory() {
  if (memory.size <= MAX_ENTRIES) return;
  for (const [key, entry] of memory) {
    if (entry.inflight) continue;
    memory.delete(key);
    if (memory.size <= MAX_ENTRIES) break;
  }
}

function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function errorBody(body) {
  if (!body || typeof body !== 'object') return null;
  return {
    message: body.detail || body.title || (Array.isArray(body.error) ? body.error[0]?.message : '') || '',
    code: body.code || '',
  };
}

async function request(path, { ifNoneMatch, attempts = 5 } = {}) {
  const accept = { Accept: 'application/json' };
  let conditional = Boolean(ifNoneMatch);
  let etag = ifNoneMatch;

  for (let attempt = 0; ; attempt++) {
    const headers = conditional ? { ...accept, 'If-None-Match': etag } : accept;
    let response;
    try {
      response = await fetch(ORIGIN + path, { method: 'GET', headers, credentials: 'omit', mode: 'cors' });
    } catch {
      if (conditional) {
        conditional = false;
        try {
          response = await fetch(ORIGIN + path, { method: 'GET', headers: accept, credentials: 'omit', mode: 'cors' });
        } catch {
          throw new ApiError('Could not reach make.fun. Check your connection and try again.', { status: 0 });
        }
      } else {
        throw new ApiError('Could not reach make.fun. Check your connection and try again.', { status: 0 });
      }
    }

    if (response.status === 503 && attempt < attempts) {
      const retryAfter = Number(response.headers.get('Retry-After'));
      await wait(Number.isFinite(retryAfter) && retryAfter > 0 ? Math.min(8, retryAfter) * 1000 : Math.min(5, attempt + 1) * 1000);
      continue;
    }
    return response;
  }
}

async function apiGet(path, { force = false, attempts = 5 } = {}) {
  const cached = memory.get(path);
  const fresh = cached?.data !== undefined && Date.now() - cached.at < TTL_MS;

  if (!force && fresh) {
    stats.memoryHits++;
    emit();
    return cached.data;
  }
  if (cached?.inflight) return cached.inflight;

  const entry = { ...(cached || {}) };
  const promise = (async () => {
    stats.requests++;
    if (entry.etag) stats.revalidated++;
    const response = await request(path, { ifNoneMatch: entry.etag, attempts });

    if (response.status === 304 && entry.data !== undefined) {
      entry.at = Date.now();
      entry.inflight = null;
      const etag = response.headers.get('etag');
      if (etag) entry.etag = etag;
      stats.notModified++;
      stats.lastUpdated = new Date().toISOString();
      emit();
      return entry.data;
    }

    if (!response.ok) {
      if (entry.data !== undefined && response.status >= 500) {
        entry.at = Date.now() - TTL_MS;
        entry.inflight = null;
        stats.stale++;
        emit();
        return entry.data;
      }
      let parsed = null;
      try { parsed = errorBody(await response.json()); } catch { /* non-JSON error */ }
      stats.errors++;
      emit();
      throw new ApiError(parsed?.message || `make.fun answered ${response.status}.`, {
        status: response.status,
        code: parsed?.code || '',
        retryAfter: Number(response.headers.get('Retry-After')) || 0,
      });
    }

    let data;
    try {
      data = await response.json();
    } catch {
      stats.errors++;
      emit();
      throw new ApiError('make.fun sent an answer this page could not read.', { status: response.status });
    }

    entry.data = data;
    entry.etag = response.headers.get('etag') || null;
    entry.at = Date.now();
    entry.inflight = null;
    trimMemory();
    stats.network++;
    stats.lastUpdated = new Date().toISOString();
    emit();
    return data;
  })();

  entry.inflight = promise;
  memory.set(path, entry);

  try {
    return await promise;
  } catch (error) {
    const current = memory.get(path);
    if (current?.inflight === promise) {
      if (current.data !== undefined) current.inflight = null;
      else memory.delete(path);
    }
    throw error;
  }
}

export function cacheSummary() {
  const parts = [];
  if (stats.network) parts.push(`${stats.network} API ${stats.network === 1 ? 'read' : 'reads'}`);
  if (stats.notModified) parts.push(`${stats.notModified} revalidated (304)`);
  if (stats.revalidated && !stats.notModified) parts.push(`${stats.revalidated} ETag ${stats.revalidated === 1 ? 'check' : 'checks'}`);
  if (stats.memoryHits) parts.push(`${stats.memoryHits} cache ${stats.memoryHits === 1 ? 'hit' : 'hits'}`);
  if (stats.stale) parts.push(`${stats.stale} kept from cache on error`);
  if (!parts.length) parts.push('Waiting for make.fun');
  parts.push(`${memory.size} ${memory.size === 1 ? 'answer' : 'answers'} in memory`);
  return parts.join(' · ');
}

/** The board: every public competition, with activity rows cut to their times. */
export function getBounties(options) {
  return apiGet('/api/competitions?activity=times', options).then((data) => {
    if (Array.isArray(data?.items)) boardItems = data.items;
    return data;
  });
}

/** A bounty already present in the board answer, if one has been read. */
export function getBoardBounty(slug) {
  return boardItems?.find((item) => item.slug === slug) || null;
}

/** One bounty, without its (often huge) list of entries. */
export function getBounty(slug, options) {
  return apiGet(`/api/competitions/${encodeURIComponent(slug)}?submissions=summary`, options);
}

/** A bounty's standings: ten whole rows, then light stubs. */
export function getLeaderboard(slug, { phase = '' } = {}) {
  const query = ['rows=first'];
  if (phase) query.push(`phase=${encodeURIComponent(phase)}`);
  return apiGet(`/api/competitions/${encodeURIComponent(slug)}/leaderboard?${query.join('&')}`);
}

/** An account's public profile. */
export function getProfile(handle) {
  return apiGet(`/api/profiles/${encodeURIComponent(handle)}`);
}
```

### app/core.js (6923 bytes)

```js

const NUM = new Intl.NumberFormat('en-US');
const DM = new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const TU = new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'UTC' });

export const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

export function money(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '—';
  const whole = Math.abs(n - Math.round(n)) < 0.005;
  return n.toLocaleString('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: whole ? 0 : 2, maximumFractionDigits: whole ? 0 : 2 });
}

export function num(value) {
  return Number.isFinite(Number(value)) ? NUM.format(Number(value)) : '—';
}

export function plural(count, singular, many = `${singular}s`) {
  return `${num(count)} ${Number(count) === 1 ? singular : many}`;
}

export function parseDate(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? null : d;
}

export function deadlineShort(iso) {
  const d = parseDate(iso);
  return d ? `${DM.format(d)} · ${TU.format(d)} UTC` : '—';
}

export function timeLeftLabel(iso, now = Date.now()) {
  const d = parseDate(iso);
  if (!d) return '—';
  const ms = d.getTime() - now;
  if (ms <= 0) return 'Closed';
  const m = Math.floor(ms / 60000), h = Math.floor(m / 60), days = Math.floor(h / 24);
  const text = days ? `${days}d ${h % 24}h` : h ? `${h}h ${m % 60}m` : m ? `${m}m` : '<1m';
  return `${text} left`;
}

export function bountyState(bounty, now = Date.now()) {
  const status = bounty?.status;
  if (status === 'resolved' || bounty?.resolvedAt) return { key: 'resolved', label: 'Resolved', full: 'Results published' };
  if (status === 'open') {
    const deadline = parseDate(bounty?.deadline);
    return !deadline || deadline.getTime() > now
      ? { key: 'live', label: 'Open', full: 'Accepting entries' }
      : { key: 'closed', label: 'Closed', full: 'Entries closed, awaiting results' };
  }
  if (status === 'closed') return { key: 'closed', label: 'Closed', full: 'Entries closed, awaiting results' };
  if (status === 'draft') return { key: 'draft', label: 'Draft', full: 'Not published' };
  const label = titleCase(status || 'Unknown');
  return { key: status || 'unknown', label, full: label };
}

function titleCase(value) {
  return String(value ?? '').replace(/(^|[\s-])([a-z])/g, (_, a, b) => a + b.toUpperCase());
}

function truncate(value, length = 180) {
  const text = String(value ?? '').replace(/\s+/g, ' ').trim();
  return text.length > length ? `${text.slice(0, length - 1).trimEnd()}…` : text;
}

export function deckLine(value, title, length = 0) {
  let text = String(value ?? '').replace(/[#*_`>]/g, '').replace(/\s+/g, ' ').trim();
  const prefix = String(title ?? '').trim();
  if (prefix && text.toLowerCase().startsWith(`${prefix.toLowerCase()}:`)) {
    text = text.slice(prefix.length + 1).trim();
    if (text) text = text[0].toUpperCase() + text.slice(1);
  }
  return length ? truncate(text, length) : text;
}

export function el(tag, attrs = null, ...children) {
  const node = document.createElement(tag);
  if (attrs) {
    for (const [key, value] of Object.entries(attrs)) {
      if (value == null || value === false) continue;
      if (key === 'class') node.className = value;
      else node.setAttribute(key, value === true ? '' : String(value));
    }
  }
  for (const child of children.flat(Infinity)) {
    if (child == null || child === false) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

export function replace(node, ...children) {
  node.replaceChildren(...children.flat(Infinity).filter((child) => child != null && child !== false));
  return node;
}

export function setText(node, text) {
  if (node) node.textContent = text == null ? '' : String(text);
}

export function apiAssetUrl(url) {
  if (!url || typeof url !== 'string' || url.startsWith('data:')) return null;
  return /^https?:\/\//i.test(url) ? url : `https://make.fun${url.startsWith('/') ? '' : '/'}${url}`;
}

export function apiImage(url, attrs = {}) {
  const src = apiAssetUrl(url);
  if (!src) return null;
  const img = el('img', { crossorigin: 'anonymous', alt: attrs.alt ?? '', class: attrs.class, loading: 'lazy', decoding: 'async', referrerpolicy: 'no-referrer' });
  if (attrs.fail) img.addEventListener('error', attrs.fail, { once: true });
  img.src = src;
  return img;
}

export function emptyPanel({ kicker = '', title, body, actions = [] }) {
  return el(
    'section',
    { class: 'empty-panel' },
    kicker ? el('p', { class: 'kicker' }, kicker) : null,
    el('h2', { class: 'empty-title' }, title),
    body ? el('p', { class: 'empty-body' }, body) : null,
    actions.length ? el('div', { class: 'empty-actions' }, ...actions) : null,
  );
}

function safeDecode(value) {
  try { return decodeURIComponent(value); } catch { return value; }
}

export function parseRoute(hash = location.hash) {
  const raw = String(hash || '').replace(/^#/, '');
  const at = raw.indexOf('?');
  const params = new URLSearchParams(at >= 0 ? raw.slice(at + 1) : '');
  const parts = (at >= 0 ? raw.slice(0, at) : raw).split('/').filter(Boolean).map(safeDecode);

  if (!parts.length) return { kind: 'board', params, key: 'board' };
  if (parts[0] === 'bounty' && parts[1]) {
    if (parts.length === 2) return { kind: 'bounty', slug: parts[1], params, key: `bounty:${parts[1]}` };
    if (parts.length === 3 && parts[2] === 'leaderboard') {
      const phase = params.get('phase') === 'final' ? ':final' : '';
      return { kind: 'leaderboard', slug: parts[1], params, key: `leaderboard:${parts[1]}${phase}` };
    }
  }
  if (parts[0] === 'u' && parts.length === 2) return { kind: 'profile', handle: parts[1], params, key: `profile:${parts[1]}` };
  return { kind: 'notfound', params, key: `notfound:${raw}` };
}

export function replaceHash(hash) {
  if (location.hash !== hash) history.replaceState(null, '', hash);
}

export function boardHash({ view = 'live', sort = 'ending', page = 1 } = {}) {
  const params = new URLSearchParams();
  if (view && view !== 'all') params.set('view', view);
  if (sort && sort !== 'ending') params.set('sort', sort);
  if (page > 1) params.set('page', String(page));
  const query = params.toString();
  return `#/${query ? `?${query}` : ''}`;
}

export function leaderboardHash(slug, page = 1, phase = '') {
  const params = new URLSearchParams();
  if (phase) params.set('phase', phase);
  if (page > 1) params.set('page', String(page));
  const query = params.toString();
  return `#/bounty/${encodeURIComponent(slug)}/leaderboard${query ? `?${query}` : ''}`;
}

export const profileHash = (handle) => `#/u/${encodeURIComponent(handle)}`;
export const bountyHash = (slug) => `#/bounty/${encodeURIComponent(slug)}`;
