      ? `<span class="r-winner">Won by <a href="${esc(profileHash(winner.handle))}" class="inline-link">@${esc(winner.handle)}</a>${winner.amountUsd ? ` · ${esc(money(winner.amountUsd))}` : ''}</span>`
      : '';

